type Event = {
  turnId: string;
  kind: string;
  [key: string]: unknown;
};

type Tool = {
  id: string;
  title: string;
  status: "pending" | "running" | "completed" | "failed";
  output: string;
};

type Turn = {
  text: string;
  tools: Tool[];
  stopReason: string | null;
};

export function assembleTurn(turnId: string, events: Event[]): Turn {
  let text = "";
  let stopReason: string | null = null;
  const tools = new Map<string, Tool>();

  for (const event of events) {
    if (event.turnId !== turnId) continue;

    if (event.kind === "done") {
      stopReason = event.stopReason as string;
      break;
    }

    if (event.kind === "message") {
      const message = event.text as string;
      text = event.mode === "replace" ? message : text + message;
      continue;
    }

    if (event.kind !== "tool") continue;

    const id = event.id as string;
    let tool = tools.get(id);

    if (tool === undefined) {
      tool = { id, title: "", status: "pending", output: "" };
      tools.set(id, tool);
    }

    if (event.title !== undefined) {
      tool.title = event.title as string;
    }

    if (event.status !== undefined) {
      tool.status = event.status as Tool["status"];
    }

    if (event.output === null) {
      tool.output = "";
    } else if (typeof event.output === "string") {
      tool.output =
        event.outputMode === "replace"
          ? event.output
          : tool.output + event.output;
    }
  }

  return { text, tools: Array.from(tools.values()), stopReason };
}
